Lemma sc_call_cg : forall (pc : Z) (k : cfgkey) (dflt res : word) (errz : bool), cg_stmt H pc k dflt res errz ->
  forall (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word)
         (saved gap : list cell) (h32 j472 shb : list byte) (errv : word) (cs lc : list cell) (m : mem)
         (rax gp t0 t1 t2 a5 a6 a7 xs2 xs3 xs5 xs6 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (Q : machine_state -> Prop),
  sc_invt s LB LF S ioc regb cfgb lo shi spa ff fp sp saved gap h32 j472 shb errv cs lc m ->
  sc_side LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  F = bvmap_empty -> fc = Z_to_bv 32 0 -> bv_unsigned rax mod 2 = 0 ->
  (forall (m' : mem) (ff' fp' : Z) (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word),
     sc_invt s LB LF S ioc regb cfgb lo shi spa ff fp sp saved gap h32 j472 shb (if errz then wz 0 else errv) cs lc m' ->
     fresh_frame H ((3, ff, fp) :: LF) 2 ff' fp' ->
     munch ([(lo, spa); (AERRNO, AERRNO + 4)]%Z ++ fr2_XS H ff' fp') m m' -> wmono bsegs m m' ->
     evt bsegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) res a1' a2' a3' a4' a5' a6' a7'
                           xs2 xs3 (Z_to_bv 64 S) xs5 xs6 xs7 (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3' t4' t5' t6')
                  F (ret_pc rax) fc None m' (seg_rom bsegs))) ->
  evt bsegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit k)) dflt (wz 0) a5 a6 a7
                        xs2 xs3 (Z_to_bv 64 S) xs5 xs6 xs7 (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
               F (Z_to_bv 64 pc) fc None m (seg_rom bsegs)).
